CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','parent','mentor','admin')), synthetic INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE recovery(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE relationships(actor_id INTEGER NOT NULL REFERENCES users(id), student_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('parent','mentor','admin')), scopes TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(actor_id,student_id,kind));
CREATE TABLE stages(student_id INTEGER NOT NULL REFERENCES users(id), stage INTEGER NOT NULL CHECK(stage BETWEEN 1 AND 8), draft TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'empty' CHECK(status IN ('empty','draft','submitted','complete')), revision INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(student_id,stage));
CREATE TABLE evidence(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), stakeholder TEXT NOT NULL, source TEXT NOT NULL, type TEXT NOT NULL, statement TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, corrected_from INTEGER REFERENCES evidence(id));
CREATE TABLE snapshots(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), version INTEGER NOT NULL, inputs TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(student_id,version));
CREATE TABLE runs(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), snapshot_id INTEGER NOT NULL REFERENCES snapshots(id), config_version INTEGER NOT NULL, status TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE steps(id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id), step INTEGER NOT NULL CHECK(step BETWEEN 1 AND 4), attempt INTEGER NOT NULL, status TEXT NOT NULL, input TEXT NOT NULL, output TEXT, summary TEXT NOT NULL, error TEXT, created TEXT NOT NULL, UNIQUE(run_id,step,attempt));
CREATE TABLE reports(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), run_id INTEGER NOT NULL REFERENCES runs(id), version INTEGER NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('generated','admin-edited')), maps TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','stale','published','superseded')), created TEXT NOT NULL, UNIQUE(student_id,version));
CREATE TABLE approvals(report_id INTEGER NOT NULL REFERENCES reports(id), actor_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('admin','mentor')), reason TEXT NOT NULL, created TEXT NOT NULL, PRIMARY KEY(report_id,actor_id,role));
CREATE TABLE publications(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), report_id INTEGER NOT NULL UNIQUE REFERENCES reports(id), actor_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL);
CREATE TABLE notes(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), actor_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('session','information-request')), text TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), student_id INTEGER REFERENCES users(id), action TEXT NOT NULL, record_id INTEGER, reason TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, body TEXT NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, window INTEGER NOT NULL);
